def update_note(record_id, note):
    (cloud_db().table("health_lab_records").update({"note": note})
     .eq("family_id", FAMILY_ID).eq("id", int(record_id)).execute())
    clear_cache()


@st.cache_data(ttl=3, show_spinner=False)
def load_family_logs(person=None, section=None):
    q = cloud_db().table("family_health_logs").select("*").eq("family_id", FAMILY_ID)
    if person: q = q.eq("person", person)
    if section: q = q.eq("section", section)
    res = q.order("record_date", desc=True).order("id", desc=True).execute()
    df = pd.DataFrame(res.data or [])
    if not df.empty:
        df["record_date"] = pd.to_datetime(df["record_date"])
    return df


def save_family_log(record_date, person, section, category="", value1=None, value2=None, value3="", note=""):
    payload = _clean_payload({
        "family_id": FAMILY_ID,
        "record_date": _date_iso(record_date),
        "person": person,
        "section": section,
        "category": category,
        "value1": value1,
        "value2": value2,
        "value3": value3,
        "note": note,
    })
    cloud_db().table("family_health_logs").insert(payload).execute()
    clear_cache()


def upsert_family_log_by_date(record_date, person, section, category="", value1=None, value2=None, value3="", note=""):
    db = cloud_db()
    d = _date_iso(record_date)
    res = (db.table("family_health_logs").select("id")
           .eq("family_id", FAMILY_ID).eq("record_date", d)
           .eq("person", person).eq("section", section)
           .order("id", desc=True).execute())
    rows = res.data or []
    payload = _clean_payload({
        "record_date": d, "person": person, "section": section,
        "category": category, "value1": value1, "value2": value2,
        "value3": value3, "note": note,
    })
    if rows:
        keep_id = rows[0]["id"]
        db.table("family_health_logs").update(payload).eq("family_id", FAMILY_ID).eq("id", keep_id).execute()
        for dup in rows[1:]:
            db.table("family_health_logs").delete().eq("family_id", FAMILY_ID).eq("id", dup["id"]).execute()
    else:
        payload["family_id"] = FAMILY_ID
        db.table("family_health_logs").insert(payload).execute()
    clear_cache()


def delete_family_log(record_id):
    (cloud_db().table("family_health_logs").delete()
     .eq("family_id", FAMILY_ID).eq("id", int(record_id)).execute())
    clear_cache()

